import subprocess
import sys
from datetime import date
from pathlib import Path

ROOT = Path("/Users/dali/coldmail/tapebackup")
sys.path.insert(0, str(ROOT / "scripts"))
import generate_blog_posts as G  # noqa: E402

PUBLISHED = date(2026, 11, 17)

post_data = {'slug': 'lto-10-price-compatibility-buyers-guide', 'title': 'LTO-10 Price and Compatibility Guide', 'description': 'US street prices for LTO-10 drives and 30TB or 40TB media on 23 October 2026, compatibility limits, and per-TB math against LTO-9 for tape buyers.', 'category': 'Buying Guide', 'body': '<p><strong>On our October 2026 price data, LTO-10 still costs more per terabyte than LTO-9, so most tape buyers save money by staying on LTO-9. Our tapebackup.org price tracker from 23 October 2026 shows LTO-10 30TB media at $8.63 to $10.00 per native TB and external drives from $23,422, while LTO-9 media runs $5.14 to $7.17 per TB. LTO-10 only pays off when library slot count or cartridge handling outweighs media cost.</strong></p>\n\n<h2>LTO-10 drive and cartridge prices on 23 October 2026</h2>\n\n<p>Our <a href="/lto-tape-price-trend">tapebackup.org price tracker</a> recorded US street prices across major resellers on 23 October 2026. LTO-10 30TB cartridges are broadly in stock at $259.00 to $299.99, which equals $8.63 to $10.00 per native TB. LTO-10 40TB cartridges cost $491.00 to $555.00, or $12.28 to $13.88 per native TB, with Fujifilm 40TB in stock at MagStor, limited at Tape4Backup, and special order at TapeandMedia.</p>\n\n<p>LTO-10 30TB WORM cartridges were out of stock across all four brands at Tape4Backup on 23 October 2026, with out-of-stock list prices running $420.00 to $460.80 ($14.00 to $15.36 per native TB). No LTO-10 40TB WORM cartridge appeared at any seller we checked. By comparison, LTO-9 18TB cartridges cost $92.45 to $129.00 on 23 October 2026, or $5.14 to $7.17 per native TB.</p>\n\n<p>Hardware pricing widens the gap further. On 23 October 2026, external LTO-10 drives ranged from $23,422 to $24,950 in our tracker, compared with $9,199 to $15,225 for external LTO-9 drives. At BackupWorks, a Qualstar Q-Series LTO-10 SAS full-height library add-on drive (800-0110-0) was listed at $28,068 on 23 October 2026, up from $23,509 in September 2026. Tape4Backup also continued to display its banner on 23 October 2026 stating that all LTO tape prices increased from 1 September 2026.</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>Format (23 October 2026)</th>\n      <th>Native capacity</th>\n      <th>Media street price</th>\n      <th>Price per native TB</th>\n      <th>External drive range</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>LTO-9</td>\n      <td>18 TB</td>\n      <td>$92.45 to $129.00</td>\n      <td>$5.14 to $7.17</td>\n      <td>$9,199 to $15,225</td>\n    </tr>\n    <tr>\n      <td>LTO-10 30TB</td>\n      <td>30 TB</td>\n      <td>$259.00 to $299.99</td>\n      <td>$8.63 to $10.00</td>\n      <td>$23,422 to $24,950</td>\n    </tr>\n    <tr>\n      <td>LTO-10 40TB</td>\n      <td>40 TB</td>\n      <td>$491.00 to $555.00</td>\n      <td>$12.28 to $13.88</td>\n      <td>$23,422 to $24,950</td>\n    </tr>\n    <tr>\n      <td>LTO-10 30TB WORM (out of stock)</td>\n      <td>30 TB</td>\n      <td>$420.00 to $460.80</td>\n      <td>$14.00 to $15.36</td>\n      <td>$23,422 to $24,950</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>Media math: 300 TB native on LTO-9 vs LTO-10</h2>\n\n<p>A simple worked example using the lowest street prices in our 23 October 2026 tracker shows why LTO-9 wins on pure media spend for a 300 TB native archive:</p>\n\n<ul>\n  <li><strong>LTO-9 (18 TB cartridges at $92.45):</strong> 300 TB divided by 18 TB equals 16.67, so you buy 17 cartridges (306 TB total). 17 multiplied by $92.45 equals $1,571.65.</li>\n  <li><strong>LTO-10 30TB (at $259.00):</strong> 300 TB divided by 30 TB equals 10 cartridges. 10 multiplied by $259.00 equals $2,590.00, which is $1,018.35 more than LTO-9.</li>\n  <li><strong>LTO-10 40TB (at $491.00):</strong> 300 TB divided by 40 TB equals 7.5, so you buy 8 cartridges (320 TB total). 8 multiplied by $491.00 equals $3,928.00, which is $2,356.35 more than LTO-9.</li>\n</ul>\n\n<p>Add the drive cost and the difference grows. Comparing the lowest external LTO-10 drive ($23,422) against the lowest external LTO-9 drive ($9,199) in our 23 October 2026 tracker adds $14,223 upfront. In our reading, LTO-10 only makes sense today when physical slot count, library rack space, or cartridge handling time matters more than cost per TB. You can test your own retention totals in our <a href="/backup-calculator">backup calculator</a> or compare tape against spinning disk in our <a href="/why-tape/lto-vs-hdd">LTO vs HDD guide</a>.</p>\n\n<h2>Why 40TB LTO-10 exists and what changed</h2>\n\n<p>Blocks &amp; Files reported on 13 November 2025 that the <a href="https://www.blocksandfiles.com/tape/2025/11/13/lto-10-bumped-to-40-tb-as-future-tape-capacities-get-cut/1711787">LTO consortium raised LTO-10 raw capacity to 40 TB</a>, a 33 percent increase over the 30 TB cartridges initially delivered by Fujifilm and Sony with sole drive supplier IBM. LTO-10 had originally been specified for 36 TB native, and the 40 TB upgrade uses a thinner, smoother aramid-based tape ribbon substrate in place of polyethylene naphthalate (PEN) film so longer tape fits inside the standard Ultrium shell. In the same announcement, the consortium lowered its LTO-14 target to 365 TB raw (913 TB compressed) from 576 TB raw (1.44 PB compressed), a shift we covered in our <a href="/blog/lto-roadmap-365tb-tape-cartridge-capacity">LTO roadmap analysis</a>.</p>\n\n<p>TechRadar reported in September 2026 that <a href="https://www.techradar.com/pro/40tb-lto-10-tapes-quietly-go-on-sale-for-usd494-a-single-tape-can-hold-13-000-000-songs-and-up-to-100tb-of-compressed-data-with-a-400mb-s-transfer-rate">Fujifilm began selling its 40TB LTO-10 cartridge</a>, which reaches 100 TB at standard 2.5 to 1 compression and uses Barium Ferrite particles across 15,105 tracks. TechRadar noted that Fujifilm rates the cartridge at 440MB per second uncompressed (1,100MB per second compressed), a bit error rate of 1 in 10 to the 20th power, FIPS 197 compliant AES-256 encryption, and an archival life of up to 30 years under proper storage conditions. We also tracked the supply side in our <a href="/blog/fujifilm-lto-tape-production-increase">Fujifilm LTO production update</a>.</p>\n\n<h2>Compatibility limits and hardware availability</h2>\n\n<p>LTO-10 drives cannot read or write older LTO generations, as documented in our 23 October 2026 price tracker notes. If you hold an LTO-9 archive, an LTO-10 drive cannot restore those tapes, so you must keep at least one LTO-9 drive online or migrate the data before retiring older hardware.</p>\n\n<p>For 40TB media, our 23 October 2026 tracker notes confirm that existing full-height LTO-10 drives accept the 40TB cartridge, while IBM states that its own 40TB cartridges (models 564 and 664, announced 6 March 2026 in 20- and 5-packs with no street price seen) work only in IBM LTO-10 drives. Hardware choice also remains narrow on 23 October 2026: only full-height LTO-10 drives are on the market, no half-height LTO-10 drive was listed at any seller we checked (Symply had expected half-height in Q2 2026 and the LTO Program said late 2026), and no bare internal standalone LTO-10 drive price was listed at the HPE, IBM, or Quantum resellers we checked. See our <a href="/why-tape/lto-tape-drive">LTO tape drive guide</a> for form factor basics.</p>\n\n<h2>Frequently asked questions</h2>\n\n<h3>Can an LTO-10 drive read or write LTO-9 tapes?</h3>\n<p>No. Per our 23 October 2026 price tracker notes, LTO-10 drives cannot read or write any older LTO generation, including LTO-9.</p>\n\n<h3>How much does LTO-10 media cost per TB compared to LTO-9?</h3>\n<p>On 23 October 2026, tapebackup.org tracked LTO-9 18TB media at $5.14 to $7.17 per native TB, LTO-10 30TB media at $8.63 to $10.00 per native TB, and LTO-10 40TB media at $12.28 to $13.88 per native TB.</p>\n\n<h3>Do 40TB LTO-10 cartridges work in existing LTO-10 drives?</h3>\n<p>Yes, existing full-height LTO-10 drives accept the 40TB cartridge, though IBM specifies that its own 40TB cartridges work only in IBM LTO-10 drives, according to our 23 October 2026 tracker notes.</p>\n\n<h3>Are half-height or internal LTO-10 drives available yet?</h3>\n<p>No half-height LTO-10 drive and no bare internal standalone LTO-10 drive price appeared at any reseller checked by tapebackup.org on 23 October 2026, with the LTO Program pointing to late 2026 for half-height availability.</p>\n\n<h3>When is LTO-10 worth buying over LTO-9?</h3>\n<p>In our reading, LTO-10 makes sense when library slot count, rack space, or cartridge handling matters more than media cost per TB, because both LTO-10 media and external drives ($23,422 to $24,950 on 23 October 2026) cost substantially more than LTO-9.</p>\n\n<script type="application/ld+json">\n{\n  "@context": "https://schema.org",\n  "@type": "FAQPage",\n  "mainEntity": [\n    {\n      "@type": "Question",\n      "name": "Can an LTO-10 drive read or write LTO-9 tapes?",\n      "acceptedAnswer": {\n        "@type": "Answer",\n        "text": "No. Per our 23 October 2026 price tracker notes, LTO-10 drives cannot read or write any older LTO generation, including LTO-9."\n      }\n    },\n    {\n      "@type": "Question",\n      "name": "How much does LTO-10 media cost per TB compared to LTO-9?",\n      "acceptedAnswer": {\n        "@type": "Answer",\n        "text": "On 23 October 2026, tapebackup.org tracked LTO-9 18TB media at $5.14 to $7.17 per native TB, LTO-10 30TB media at $8.63 to $10.00 per native TB, and LTO-10 40TB media at $12.28 to $13.88 per native TB."\n      }\n    },\n    {\n      "@type": "Question",\n      "name": "Do 40TB LTO-10 cartridges work in existing LTO-10 drives?",\n      "acceptedAnswer": {\n        "@type": "Answer",\n        "text": "Yes, existing full-height LTO-10 drives accept the 40TB cartridge, though IBM specifies that its own 40TB cartridges work only in IBM LTO-10 drives, according to our 23 October 2026 tracker notes."\n      }\n    },\n    {\n      "@type": "Question",\n      "name": "Are half-height or internal LTO-10 drives available yet?",\n      "acceptedAnswer": {\n        "@type": "Answer",\n        "text": "No half-height LTO-10 drive and no bare internal standalone LTO-10 drive price appeared at any reseller checked by tapebackup.org on 23 October 2026, with the LTO Program pointing to late 2026 for half-height availability."\n      }\n    },\n    {\n      "@type": "Question",\n      "name": "When is LTO-10 worth buying over LTO-9?",\n      "acceptedAnswer": {\n        "@type": "Answer",\n        "text": "In our reading, LTO-10 makes sense when library slot count, rack space, or cartridge handling matters more than media cost per TB, because both LTO-10 media and external drives ($23,422 to $24,950 on 23 October 2026) cost substantially more than LTO-9."\n      }\n    }\n  ]\n}\n</script>\n\n<p>Track monthly street prices on our <a href="/lto-tape-price-trend">LTO tape price trend page</a>, size your archive with the <a href="/backup-calculator">backup calculator</a>, and read how the 40TB revision affects future generations in our <a href="/blog/lto-roadmap-365tb-tape-cartridge-capacity">LTO roadmap post</a>.</p>\n\n'}

def main():
    words = len(re.sub(r"<[^>]+>", " ", post_data["body"]).split())
    post = G.Post(
        slug=post_data["slug"],
        title=post_data["title"],
        description=post_data["description"],
        category=post_data["category"],
        published=PUBLISHED,
        minutes=max(3, round(words / 200)),
        body_html=post_data["body"]
    )
    
    assert len(post.title) + len(" | TapeBackup.org") <= 60, f"Title too long: {len(post.title) + len(' | TapeBackup.org')}"
    assert len(post.description) <= 155, f"Description too long: {len(post.description)}"
    
    post_dir = ROOT / "blog" / post.slug
    post_dir.mkdir(parents=True, exist_ok=True)
    post_html = G.render_article(post)
    (post_dir / "index.html").write_text(post_html, encoding="utf-8")
    print(f"Wrote {post_dir / 'index.html'} ({len(post_html)} bytes, {words} words)")
    
    # Update blog listing
    existing_posts = [
        G.parse_existing_post(f)
        for f in sorted((ROOT / "blog").glob("*/index.html"))
        if f.parent.name != post.slug
    ]
    all_posts = sorted([post] + existing_posts, key=lambda x: (x.published, x.slug), reverse=True)
    (ROOT / "blog" / "index.html").write_text(G.render_listing(all_posts), encoding="utf-8")
    print(f"Updated blog listing with {len(all_posts)} posts")
    
    # Update homepage cards
    home = [{"href": f"/blog/{p.slug}", "cat": p.category, "date": p.published.strftime("%b %Y"), "h": p.title} for p in all_posts[:3]]
    (ROOT / "data" / "home-blog.json").write_text(json.dumps(home, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    
    # Run full build
    print("Running build_site.py...")
    subprocess.run([sys.executable, str(ROOT / "scripts" / "build_site.py")], check=True)
    print("Build complete.")

if __name__ == "__main__":
    main()
